 			FilePath:    symbol.FilePath,
 			StartLine:   start,
 			EndLine:     end,
 			Source:      strings.Join(lines[start-1:end], "\n"),
 			Elided:      elided,
 			UnitEndLine: unitEnd,
 		})
 	}
 	if len(bodies) == 0 {
 		return nil
 	}
