 func writeDefBodiesFromReader(out io.Writer, response defResponse, read lineReader, from int) {
 	if len(response.Declarations) == 0 || read == nil {
 		return
 	}
 	records := make([]sem.SymbolRecord, 0, len(response.Declarations))
